model_config_list {
  config {
    name: 'multimodal'
    dynamic_batching {
      max_batch_size: 64
      batch_queue_capacity: 128
      fbatch_timeout_micros: 50000
      num_batch_threads: 4
      allow_precision_loss: true
    }
  }
}
```

